// ------------------------------------------------------------
// 1. Imports
// ------------------------------------------------------------
import org.elasticsearch.common.xcontent.XContentBuilder;
import org.elasticsearch.common.xcontent.XContentFactory;
import java.util.Arrays;

// ------------------------------------------------------------
// 2. Helper wrapper that matches the SDK signature
// ------------------------------------------------------------
class RootObjectMapperDoXContentParams {
    public final String builder;   // JSON string produced by XContentBuilder
    public final String params;    // JSON array string of options

    public RootObjectMapperDoXContentParams(String builder, String params) {
        this.builder = builder;
        this.params = params;
    }
}

// ------------------------------------------------------------
// 3. Main demo
// ------------------------------------------------------------
public class RootObjectMapperDemo {

    public static void main(String[] args) throws Exception {

        // --------------------------------------------------------
        // 3a. Build the mapping with the default settings you want
        // --------------------------------------------------------
        XContentBuilder builder = XContentFactory.jsonBuilder()
            .startObject()
                // Default dynamic date formats – you can add as many as you need
                .array("dynamic_date_formats",
                       "yyyy-MM-dd",
                       "yyyy/MM/dd",
                       "dd-MM-yyyy")
                // Default dynamic templates – placeholder names
                .array("dynamic_templates",
                       "template1",
                       "template2")
                // Enable date detection
                .field("date_detection", true)
                // Enable numeric detection
                .field("numeric_detection", true)
            .endObject();

        // --------------------------------------------------------
        // 3b. Convert the builder to a string (what the SDK expects)
        // --------------------------------------------------------
        String builderStr = builder.toString();   // e.g. {"dynamic_date_formats":["yyyy-MM-dd","yyyy/MM/dd","dd-MM-yyyy"],"dynamic_templates":["template1","template2"],"date_detection":true,"numeric_detection":true}

        // --------------------------------------------------------
        // 3c. Build the params array – include defaults & skip runtime fields
        // --------------------------------------------------------
        // The SDK expects a JSON‑encoded array of key/value pairs.
        // Here we use the keys that the SDK recognises:
        //   "include_defaults" : true
        //   "skip_runtime_fields" : true
        String paramsStr = "[\"include_defaults\",true,\"skip_runtime_fields\",true]";

        // --------------------------------------------------------
        // 3d. Call the SDK helper
        // --------------------------------------------------------
        // In real code you would probably have a static import or a direct call.
        // The following line mimics the signature you posted:
        functions.RootObjectMapper_doXContent(
            new RootObjectMapperDoXContentParams(builderStr, paramsStr)
        );

        // --------------------------------------------------------
        // 3e. (Optional) Print the resulting XContent to verify
        // --------------------------------------------------------
        System.out.println("XContent produced by RootObjectMapper_doXContent:");
        System.out.println(builderStr);   // This is what the SDK would write out
    }
}
